// ================================================================
// W2B — BACKFILL realized_r (one-shot)
// Recalcule realized_r pour les trades CLÔTURÉS qui n'en ont pas,
// selon la convention W2A_V3.0_PARTIAL. N'émet QUE les lignes à corriger.
//
// Convention : R = |entry - stop_loss|
//   stopped_out         -> -1.0
//   invalidated         ->  0
//   expired_no_entry    ->  0
//   tp1_hit             -> +0.5 * TP1_R
//   tp2_hit             -> +0.5 * TP1_R + 0.5 * TP2_R
//   tp1_hit_expired / expired_after_entry -> exit price inconnu -> SKIP
// ================================================================

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.').trim());
  return isNaN(n) ? null : n;
}

function computeR(outcome, entry, sl, tp1, tp2) {
  if (entry === null || sl === null) return null;
  const risk = Math.abs(entry - sl);
  if (risk === 0) return null;
  const tp1R = tp1 !== null ? Math.abs(tp1 - entry) / risk : 0;
  const tp2R = tp2 !== null ? Math.abs(tp2 - entry) / risk : 0;
  switch (outcome) {
    case 'stopped_out':      return -1.0;
    case 'invalidated':      return 0;
    case 'expired_no_entry': return 0;
    case 'tp1_hit':          return 0.5 * tp1R;
    case 'tp2_hit':          return 0.5 * tp1R + 0.5 * tp2R;
    default:                 return null; // tp1_hit_expired / expired_after_entry / pending
  }
}

const out = [];
let total = 0, sumR = 0, skipped = 0;

for (const item of $input.all()) {
  const r = item.json;
  if (!r.signal_id) continue;
  if (String(r.trade_status).trim() !== 'closed') continue;
  if (r.realized_r !== undefined && String(r.realized_r).trim() !== '') continue; // déjà rempli

  const val = computeR(
    String(r.outcome || '').trim(),
    num(r.entry), num(r.stop_loss), num(r.tp1), num(r.tp2)
  );
  if (val === null) { skipped++; continue; }

  total++; sumR += val;
  out.push({ json: { signal_id: r.signal_id, realized_r: +val.toFixed(3) } });
}

if (out.length === 0) {
  return [{ json: { info: 'Rien à backfiller', backfilled: 0, skipped } }];
}

// ligne de contrôle en tête (n'est PAS écrite car sans signal_id -> filtrée en aval si besoin)
console.log(`[BACKFILL] ${total} lignes, bilan ${sumR.toFixed(2)} R, ${skipped} non décidables`);
return out;
